PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS media_accounts (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, logo_url TEXT, whatsapp TEXT DEFAULT '', facebook TEXT DEFAULT '', telegram TEXT DEFAULT '', whatsapp_channel TEXT DEFAULT '', is_verified INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tuitions (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, city TEXT NOT NULL DEFAULT '', area TEXT NOT NULL DEFAULT '', tuition_type TEXT NOT NULL DEFAULT 'Home Tutoring', status TEXT NOT NULL DEFAULT 'available' CHECK (status IN ('available','paused','expired','deleted')), classes_json TEXT NOT NULL DEFAULT '[]', group_name TEXT DEFAULT '', custom_group TEXT DEFAULT '', subjects_json TEXT NOT NULL DEFAULT '[]', custom_subject TEXT DEFAULT '', medium TEXT DEFAULT '', teacher_gender TEXT NOT NULL DEFAULT 'Any', preferred_institution TEXT DEFAULT '', special_requirement TEXT DEFAULT '', student_gender TEXT NOT NULL DEFAULT 'Any', student_count INTEGER, days_per_week INTEGER, duration TEXT DEFAULT '', preferred_time TEXT DEFAULT '', salary INTEGER, negotiable INTEGER NOT NULL DEFAULT 0 CHECK (negotiable IN (0,1)), media_id INTEGER, media_name TEXT NOT NULL DEFAULT 'TuitionBD Admin', media_whatsapp TEXT DEFAULT '', media_charge TEXT DEFAULT '', charge_type TEXT DEFAULT '', charge_amount REAL, charge_basis TEXT DEFAULT '', posted_at TEXT NOT NULL, expires_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_draft INTEGER NOT NULL DEFAULT 0, custom_class TEXT DEFAULT '', featured INTEGER NOT NULL DEFAULT 0, custom_fields TEXT NOT NULL DEFAULT '{}', FOREIGN KEY (media_id) REFERENCES media_accounts(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_type TEXT NOT NULL CHECK (user_type IN ('admin','media')), user_id INTEGER, username TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, tuition_id INTEGER NOT NULL, reason TEXT NOT NULL, details TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (tuition_id) REFERENCES tuitions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS activity_logs (id TEXT PRIMARY KEY, actor_role TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT, entity_id TEXT, metadata TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS site_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_tuitions_status ON tuitions(status, expires_at);
CREATE INDEX IF NOT EXISTS idx_tuitions_filters ON tuitions(city, area, tuition_type, days_per_week);
CREATE INDEX IF NOT EXISTS idx_tuitions_featured ON tuitions(featured, posted_at);
CREATE INDEX IF NOT EXISTS idx_reports_status ON reports(status, created_at);
